# Авто-добавление кириллических ключей по уже имеющимся городам постсоветских стран (без РФ).
def _ps_norm_keep_spaces(_s):
    _s = (_s or "").strip().lower()
    if not _s:
        return ""
    _s = _s.replace("ё", "е").replace("–", "-").replace("—", "-").replace("−", "-")
    out = []
    prev_space = False
    for ch in _s:
        if ch.isalnum() or ch in (" ", "-"):
            if ch == " ":
                if not prev_space:
                    out.append(" ")
                prev_space = True
            elif ch == "-":
                out.append("-")
                prev_space = False
            else:
                out.append(ch)
                prev_space = False
        else:
            # любой разделитель превращаем в пробел
            if not prev_space:
                out.append(" ")
                prev_space = True
    _s = "".join(out).strip()
    while "  " in _s:
        _s = _s.replace("  ", " ")
    return _s

_ps_items = list(PLACES_POPULAR.items())
for _k, _v in _ps_items:
    try:
        if _v[1] not in _POST_SOVIET_COUNTRIES:
            continue
        _ru_name = _v[0]
        _base = _ps_norm_keep_spaces(_ru_name).replace("-", " ").strip()
        while "  " in _base:
            _base = _base.replace("  ", " ")
        if not _base:
            continue

        _k_space = _base
        _k_dash = _base.replace(" ", "-")
        _k_join = _base.replace(" ", "")

        for _kk in (_k_space, _k_dash, _k_join):
            if not _kk:
                continue
            if _kk not in PLACES_POPULAR:
                PLACES_POPULAR[_kk] = _v
    except Exception:
        # Ничего не ломаем, просто пропускаем проблемную запись
        pass

